-- 157 · PACS only: heads NABARD's Common Accounting System names and the PACS chart lacked.
-- GENERATED by scripts/gen-migration-157.mjs from the code's own ACCOUNTS_TO_ADD_157 list — do not edit by hand.
--
-- WHY: CAS for PACS puts a profit on sale of a capital asset in Capital Reserve, shows subsidies for the society as
-- a fund and subsidies held for members as an outside liability, and charges loan provisions to the P&L (standard
-- assets under liabilities, NPA provision netted against loans). The PACS chart had no head for any of them.
--
-- WHAT: for every society whose chart has the PACS-only head 4303 "Govt Subsidy / NABARD Grant", add each account
-- it lacks — skip when the id exists, when another account already shows that code, or when an account with the
-- same name and type exists; only where the parent group exists. Opening balance 0. INSERT only, "on conflict do
-- nothing": no existing row is changed or removed, so no report figure changes.
-- Run supabase/diagnostics/preview_157_pacs_cas_heads.sql first. Undo: 157_..._down.sql.
-- NO temp tables — the SQL Editor's "Run and enable RLS" splits statements.

begin;

insert into public.accounts (id, society_id, name, "nameHi", type, "openingBalance", "openingBalanceType", "isSystem", "isGroup", "parentId", subtype, jurisdiction)
select v.id, s.society_id, v.name, v."nameHi", v.type, 0, v."openingBalanceType", v."isSystem", v."isGroup", v."parentId", v.subtype,
       (select a.jurisdiction from public.accounts a where a.society_id = s.society_id and a.jurisdiction is not null limit 1)
  from (select distinct society_id from public.accounts) s
 cross join (values
    ('1297', 'Subsidy for Society (Capital Grant)', 'समिति हेतु अनुदान (पूँजीगत)', 'equity', 'credit', false, false, '1200', 'reserve', '4303', 'Govt Subsidy / NABARD Grant', 0),
    ('1298', 'Capital Reserve', 'पूँजी संचय', 'equity', 'credit', false, false, '1200', 'reserve', '4303', 'Govt Subsidy / NABARD Grant', 1),
    ('2194', 'Provision for NPAs', 'NPA प्रावधान', 'liability', 'credit', false, false, '2100', 'current_liability', '4303', 'Govt Subsidy / NABARD Grant', 2),
    ('2195', 'Provision for Standard Assets', 'मानक परिसंपत्ति प्रावधान', 'liability', 'credit', false, false, '2100', 'current_liability', '4303', 'Govt Subsidy / NABARD Grant', 3),
    ('2199', 'Subsidy held for Members', 'सदस्यों हेतु अनुदान (देय)', 'liability', 'credit', false, false, '2100', 'current_liability', '4303', 'Govt Subsidy / NABARD Grant', 4),
    ('5498', 'Loan Loss Provisions', 'ऋण हानि प्रावधान', 'expense', 'debit', false, false, '5400', 'operational_expense', '4303', 'Govt Subsidy / NABARD Grant', 5)
  ) as v(id, name, "nameHi", type, "openingBalanceType", "isSystem", "isGroup", "parentId", subtype, needs_id, needs_name, ord)
 where not exists (select 1 from public.accounts a where a.society_id = s.society_id and a.id = v.id)
   and not exists (select 1 from public.accounts a where a.society_id = s.society_id and a.code = v.id)
   and not exists (select 1 from public.accounts a where a.society_id = s.society_id and lower(trim(a.name)) = lower(trim(v.name)) and a.type = v.type)
   and (v.needs_id is null or exists (select 1 from public.accounts n where n.society_id = s.society_id and n.id = v.needs_id and lower(trim(n.name)) = lower(trim(v.needs_name))))
   and exists (select 1 from public.accounts p where p.society_id = s.society_id and p.id = v."parentId")
on conflict do nothing;

insert into public.app_migrations (version, name) values ('157', 'pacs_cas_heads')
  on conflict (version) do nothing;

commit;

notify pgrst, 'reload schema';
